sp_widget.client_script:
api.controller = function(spModal) {

    var c = this;

    c.hrRemarks =
        c.data.leave &&
        c.data.leave.hr_remarks
        ? c.data.leave.hr_remarks
        : "";

    c.processing = false;

    c.actionMessage = "";

    c.actionSuccess = false;


    // =====================================================
    // APPROVE LEAVE
    // =====================================================

    c.approveLeave = function() {

        if (c.processing) {
            return;
        }

        spModal.confirm(
            "Are you sure you want to approve Leave Request " +
            c.data.leave.number +
            "?"
        ).then(function(confirmed) {

            if (!confirmed) {
                return;
            }

            processDecision(
                'approve'
            );

        });

    };


    // =====================================================
    // REJECT LEAVE
    // =====================================================

    c.rejectLeave = function() {

        if (c.processing) {
            return;
        }


        var remarks =
            (c.hrRemarks || "")
                .trim();


        if (!remarks) {

            c.actionSuccess = false;

            c.actionMessage =
                "Please enter HR Remarks before rejecting the Leave Request.";

            return;
        }


        spModal.confirm(
            "Are you sure you want to reject Leave Request " +
            c.data.leave.number +
            "?"
        ).then(function(confirmed) {

            if (!confirmed) {
                return;
            }

            processDecision(
                'reject'
            );

        });

    };


    // =====================================================
    // PROCESS DECISION
    // =====================================================

    function processDecision(
        decision
    ) {

        c.processing = true;

        c.actionMessage = "";


        c.server.get({

            action:
                decision,

            leave_sys_id:
                c.data.leave.sys_id,

            hr_remarks:
                c.hrRemarks || ""

        }).then(function(response) {

            c.processing = false;


            var result =
                response &&
                response.data
                ? response.data.actionResult
                : null;


            if (!result) {

                c.actionSuccess = false;

                c.actionMessage =
                    "The Leave Request decision could not be processed.";

                return;
            }


            c.actionSuccess =
                result.success === true;

            c.actionMessage =
                result.message || "";


            if (
                result.success
            ) {

                setTimeout(
                    function() {

                        window.location.href =
                            "?id=hr_leave_approval_dashboard";

                    },
                    1400
                );

            }

        }, function() {

            c.processing = false;

            c.actionSuccess = false;

            c.actionMessage =
                "An unexpected error occurred while processing the Leave Request.";

        });

    }

};

sp_widget.css:
.hlr-page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 28px 22px 45px;
  color: #14213d;
}

.hlr-page * {
  box-sizing: border-box;
}


/* =========================================
   HEADER
   ========================================= */

.hlr-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 25px;
  margin-bottom: 24px;
}

.hlr-back {
  display: inline-block;
  margin-bottom: 12px;
  color: #2563eb;
  text-decoration: none;
  font-size: 12px;
}

.hlr-back:hover {
  text-decoration: underline;
}

.hlr-header h1 {
  margin: 0 0 7px;
  color: #172554;
  font-size: 28px;
  font-weight: 700;
}

.hlr-header p {
  margin: 0;
  color: #7c879b;
  font-size: 12px;
  line-height: 1.6;
}

.request-number-card {
  min-width: 185px;
  padding: 14px 18px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  box-shadow: 0 3px 12px rgba(15, 23, 42, .05);
}

.request-number-card span {
  display: block;
  margin-bottom: 5px;
  color: #94a3b8;
  font-size: 10px;
}

.request-number-card strong {
  color: #2563eb;
  font-size: 15px;
}


/* =========================================
   SUMMARY
   ========================================= */

.hlr-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 15px;
  margin-bottom: 20px;
}

.hlr-summary-card {
  padding: 18px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  box-shadow: 0 3px 12px rgba(15, 23, 42, .04);
}

.hlr-summary-card > span {
  display: block;
  margin-bottom: 8px;
  color: #8390a5;
  font-size: 10px;
}

.hlr-summary-card strong {
  color: #172554;
  font-size: 12px;
}


/* =========================================
   STATUS
   ========================================= */

.status-pill {
  display: inline-block;
  padding: 5px 10px;
  border-radius: 20px;
  font-size: 9px;
  font-weight: 700;
}

.status-pill.pending {
  background: #fff4d8;
  color: #b56600;
}

.status-pill.approved {
  background: #dcfce7;
  color: #15803d;
}

.status-pill.rejected {
  background: #fee2e2;
  color: #b91c1c;
}


/* =========================================
   MAIN CARD
   ========================================= */

.hlr-card {
  margin-bottom: 20px;
  padding: 22px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  box-shadow: 0 4px 15px rgba(15, 23, 42, .045);
}

.hlr-card-header {
  margin-bottom: 18px;
}

.hlr-card-header h2 {
  margin: 0 0 5px;
  color: #172554;
  font-size: 17px;
  font-weight: 700;
}

.hlr-card-header p {
  margin: 0;
  color: #8390a5;
  font-size: 11px;
  line-height: 1.5;
}


/* =========================================
   INFORMATION
   ========================================= */

.hlr-info-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.hlr-field label,
.remarks-field label,
.hod-information-grid label,
.final-remarks label {
  display: block;
  margin-bottom: 7px;
  color: #8490a4;
  font-size: 10px;
  font-weight: 600;
}

.hlr-field div {
  color: #172554;
  font-size: 12px;
  font-weight: 600;
}

.information-box {
  padding: 16px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 9px;
  color: #475569;
  font-size: 11px;
  line-height: 1.7;
  white-space: pre-line;
}


/* =========================================
   EMERGENCY
   ========================================= */

.emergency-box {
  margin-top: 15px;
  padding: 16px;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  border-radius: 9px;
}

.emergency-box strong {
  color: #c2410c;
  font-size: 10px;
}

.emergency-box p {
  margin: 7px 0 0;
  color: #7c2d12;
  font-size: 11px;
  line-height: 1.6;
}


/* =========================================
   SUPPORTING DOCUMENTS
   ========================================= */

.attachments-section {
  position: relative;
}

.attachment-section-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.hr-attachment-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 27px;
  height: 27px;

  padding: 0 8px;

  background: #eaf1ff;
  color: #2563eb;

  border-radius: 20px;

  font-size: 10px;
  font-weight: 700;
}


/* ATTACHMENT LIST */

.hr-attachment-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}


/* ATTACHMENT CARD */

.hr-attachment-card {
  padding: 15px;

  background: #f8fafc;

  border: 1px solid #dbe3ec;
  border-radius: 11px;
}


/* FILE HEADER */

.hr-attachment-file-header {
  display: flex;
  align-items: center;

  gap: 11px;

  margin-bottom: 14px;
}

.hr-attachment-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 40px;
  height: 40px;

  min-width: 40px;

  background: #e0f2fe;
  color: #0369a1;

  border-radius: 9px;

  font-size: 15px;
}

.hr-attachment-file-details {
  display: flex;
  flex-direction: column;

  min-width: 0;
}

.hr-attachment-name {
  color: #172554;

  font-size: 12px;
  font-weight: 700;

  word-break: break-word;
}

.hr-attachment-size {
  margin-top: 3px;

  color: #64748b;

  font-size: 10px;
}


/* =========================================
   IMAGE PREVIEW
   ========================================= */

.hr-image-preview-wrapper {
  width: 100%;

  padding: 14px;

  background: #ffffff;

  border: 1px solid #e2e8f0;
  border-radius: 9px;

  text-align: center;
}

.hr-attachment-image {
  display: block;

  width: auto;
  height: auto;

  max-width: 600px;
  max-height: 340px;

  margin: 0 auto;

  object-fit: contain;

  background: #ffffff;

  border: 1px solid #e2e8f0;
  border-radius: 8px;

  cursor: zoom-in;

  transition:
    max-width .25s ease,
    max-height .25s ease,
    transform .25s ease;
}


/* EXPANDED IMAGE */

.hr-attachment-image.hr-attachment-image-expanded {
  max-width: 100%;
  max-height: 750px;

  cursor: zoom-out;
}


/* IMAGE MESSAGE */

.hr-image-preview-message {
  display: flex;
  align-items: center;
  justify-content: center;

  gap: 6px;

  margin-top: 9px;

  color: #64748b;

  font-size: 10px;
}

.hr-image-preview-message i {
  color: #2563eb;
}


/* =========================================
   NON IMAGE DOCUMENT
   ========================================= */

.hr-document-preview {
  display: flex;
  align-items: center;

  gap: 12px;

  padding: 14px;

  background: #ffffff;

  border: 1px solid #e2e8f0;
  border-radius: 9px;
}

.hr-document-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 42px;
  height: 42px;

  min-width: 42px;

  background: #f1f5f9;
  color: #475569;

  border-radius: 8px;

  font-size: 20px;
}

.hr-document-preview strong {
  display: block;

  color: #172554;

  font-size: 11px;
  font-weight: 700;

  word-break: break-word;
}

.hr-document-preview p {
  margin: 4px 0 0;

  color: #94a3b8;

  font-size: 9px;
}


/* =========================================
   NO ATTACHMENTS
   ========================================= */

.hr-no-attachments {
  display: flex;
  align-items: flex-start;

  gap: 11px;

  padding: 15px;

  background: #f8fafc;

  border: 1px dashed #cbd5e1;
  border-radius: 9px;

  color: #64748b;
}

.hr-no-attachments > i {
  margin-top: 2px;

  color: #94a3b8;

  font-size: 15px;
}

.hr-no-attachments strong {
  display: block;

  margin-bottom: 3px;

  color: #475569;

  font-size: 11px;
}

.hr-no-attachments p {
  margin: 0;

  color: #94a3b8;

  font-size: 9px;
  line-height: 1.5;
}


/* =========================================
   HOD REVIEW
   ========================================= */

.hod-review {
  border-left: 4px solid #22c55e;
}

.hod-badge {
  display: inline-block;
  margin-bottom: 9px;
  padding: 5px 10px;
  background: #dcfce7;
  color: #15803d;
  border-radius: 15px;
  font-size: 9px;
  font-weight: 700;
}

.hod-information-grid {
  display: grid;
  grid-template-columns: 1.4fr .6fr;
  gap: 20px;
}

.workflow-information {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.workflow-information > div {
  padding: 13px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
}

.workflow-information span {
  display: block;
  margin-bottom: 5px;
  color: #94a3b8;
  font-size: 9px;
}

.workflow-information strong {
  color: #172554;
  font-size: 10px;
}


/* =========================================
   HR DECISION
   ========================================= */

.hr-decision-card {
  border-top: 4px solid #2563eb;
}

.remarks-field textarea {
  width: 100%;
  min-height: 120px;

  resize: vertical;

  padding: 13px;

  border: 1px solid #cbd5e1;
  border-radius: 9px;

  outline: none;

  color: #334155;

  font-size: 11px;
  line-height: 1.6;
}

.remarks-field textarea:focus {
  border-color: #3b82f6;

  box-shadow:
    0 0 0 2px rgba(59, 130, 246, .08);
}

.remarks-field small {
  display: block;

  margin-top: 6px;

  color: #94a3b8;

  font-size: 9px;
}


/* FINAL DECISION WARNING */

.decision-warning {
  margin-top: 18px;

  padding: 14px;

  background: #eff6ff;

  border: 1px solid #bfdbfe;
  border-radius: 9px;
}

.decision-warning strong {
  color: #1d4ed8;

  font-size: 10px;
}

.decision-warning p {
  margin: 5px 0 0;

  color: #475569;

  font-size: 10px;
  line-height: 1.6;
}


/* DECISION BUTTONS */

.decision-actions {
  display: flex;
  justify-content: flex-end;

  gap: 12px;

  margin-top: 20px;
}

.approve-btn,
.reject-btn {
  min-width: 145px;

  padding: 11px 18px;

  border-radius: 8px;

  cursor: pointer;

  font-size: 10px;
  font-weight: 700;

  transition: .2s;
}

.approve-btn {
  border: 1px solid #16a34a;

  background: #16a34a;

  color: #ffffff;
}

.approve-btn:hover {
  background: #15803d;
}

.reject-btn {
  border: 1px solid #dc2626;

  background: #ffffff;

  color: #dc2626;
}

.reject-btn:hover {
  background: #fef2f2;
}

.approve-btn:disabled,
.reject-btn:disabled {
  opacity: .55;

  cursor: not-allowed;
}


/* =========================================
   COMPLETED
   ========================================= */

.completed-card {
  padding: 35px;

  text-align: center;
}

.completed-icon {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 58px;
  height: 58px;

  margin: 0 auto 14px;

  border-radius: 50%;

  background: #dcfce7;

  color: #15803d;

  font-size: 27px;
  font-weight: bold;
}

.completed-card h2 {
  margin-bottom: 7px;

  color: #172554;
}

.completed-card > p {
  color: #64748b;

  font-size: 11px;
}

.final-remarks {
  max-width: 720px;

  margin: 20px auto;

  padding: 15px;

  text-align: left;

  background: #f8fafc;

  border-radius: 9px;
}

.final-remarks p {
  margin: 0;

  color: #475569;

  font-size: 11px;
  line-height: 1.7;
}

.dashboard-button {
  display: inline-block;

  margin-top: 5px;

  padding: 9px 15px;

  background: #2563eb;

  border-radius: 7px;

  color: #ffffff;

  text-decoration: none;

  font-size: 10px;
  font-weight: 700;
}

.dashboard-button:hover {
  background: #1d4ed8;

  color: #ffffff;

  text-decoration: none;
}


/* =========================================
   MESSAGES
   ========================================= */

.hlr-message {
  margin-bottom: 18px;

  padding: 12px 15px;

  border-radius: 8px;

  font-size: 11px;
}

.hlr-message.success {
  background: #dcfce7;

  border: 1px solid #bbf7d0;

  color: #15803d;
}

.hlr-message.error {
  background: #fee2e2;

  border: 1px solid #fecaca;

  color: #b91c1c;
}


/* =========================================
   RESPONSIVE - TABLET
   ========================================= */

@media (max-width: 900px) {

  .hlr-summary-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .hod-information-grid {
    grid-template-columns: 1fr;
  }

  .hr-attachment-image {
    max-width: 100%;
  }

}


/* =========================================
   RESPONSIVE - MOBILE
   ========================================= */

@media (max-width: 600px) {

  .hlr-page {
    padding: 18px 12px 35px;
  }


  .hlr-header {
    flex-direction: column;
  }


  .request-number-card {
    width: 100%;
  }


  .hlr-summary-grid,
  .hlr-info-grid {
    grid-template-columns: 1fr;
  }


  .attachment-section-header {
    flex-direction: row;
    align-items: flex-start;
  }


  .hr-attachment-card {
    padding: 11px;
  }


  .hr-image-preview-wrapper {
    padding: 8px;
  }


  .hr-attachment-image {
    max-width: 100%;
    max-height: 260px;
  }


  .hr-attachment-image.hr-attachment-image-expanded {
    max-width: 100%;
    max-height: 500px;
  }


  .decision-actions {
    flex-direction: column-reverse;
  }


  .approve-btn,
  .reject-btn {
    width: 100%;
  }

}

sp_widget.script:
(function() {

    var LEAVE_TABLE =
        'x_snc_unified_hr_0_leave_request';

    var APPROVAL_TABLE =
        'sysapproval_approver';

    var HR_GROUP_NAME =
        'HR Team';


    data.hasAccess = false;
    data.requestFound = false;
    data.canProcess = false;
    data.error = false;
    data.message = "";
    data.actionResult = null;
    data.leave = {};


    var userId =
        gs.getUserID();


    // =====================================================
    // FORMAT ATTACHMENT FILE SIZE
    // =====================================================

    function formatFileSize(bytes) {

        bytes =
            parseInt(bytes, 10);

        if (!bytes || bytes <= 0) {
            return "";
        }


        if (bytes < 1024) {

            return bytes + " B";
        }


        if (
            bytes <
            (1024 * 1024)
        ) {

            return (
                bytes / 1024
            ).toFixed(1) + " KB";
        }


        if (
            bytes <
            (1024 * 1024 * 1024)
        ) {

            return (
                bytes /
                (1024 * 1024)
            ).toFixed(1) + " MB";
        }


        return (
            bytes /
            (1024 * 1024 * 1024)
        ).toFixed(1) + " GB";
    }



    // =====================================================
    // CHECK WHETHER ATTACHMENT IS AN IMAGE
    // =====================================================

    function isImageAttachment(
        fileName,
        contentType
    ) {

        fileName =
            (fileName || "")
                .toLowerCase();

        contentType =
            (contentType || "")
                .toLowerCase();


        // MIME type check

        if (
            contentType.indexOf(
                'image/'
            ) === 0
        ) {

            return true;
        }


        // File extension fallback

        var imageExtensions = [

            '.png',
            '.jpg',
            '.jpeg',
            '.gif',
            '.bmp',
            '.webp'

        ];


        for (
            var i = 0;
            i < imageExtensions.length;
            i++
        ) {

            if (
                fileName.lastIndexOf(
                    imageExtensions[i]
                ) ===

                fileName.length -
                imageExtensions[i].length
            ) {

                return true;
            }

        }


        return false;
    }



    // =====================================================
    // GET LEAVE REQUEST ATTACHMENTS
    // =====================================================

    function getLeaveAttachments(
        requestSysId
    ) {

        var attachments = [];


        var glideAttachment =
            new GlideSysAttachment();


        var attachmentGR =
            glideAttachment.getAttachments(
                LEAVE_TABLE,
                requestSysId
            );


        while (
            attachmentGR.next()
        ) {


            var attachmentSysId =
                attachmentGR.getUniqueValue();


            var fileName =
                attachmentGR.getValue(
                    'file_name'
                ) || "";


            var contentType =
                attachmentGR.getValue(
                    'content_type'
                ) || "";


            var sizeBytes =
                attachmentGR.getValue(
                    'size_bytes'
                ) || "0";


            var isImage =
                isImageAttachment(
                    fileName,
                    contentType
                );


            attachments.push({

                sys_id:
                    attachmentSysId,


                file_name:
                    fileName,


                content_type:
                    contentType,


                size:
                    formatFileSize(
                        sizeBytes
                    ),


                is_image:
                    isImage,


                // Used by HTML image preview

                preview_url:
                    "/sys_attachment.do?sys_id=" +
                    attachmentSysId

            });

        }


        return attachments;
    }



    // =====================================================
    // ACCESS CHECK - HR TEAM ONLY
    // =====================================================

    if (
        !gs.getUser()
            .isMemberOf(
                HR_GROUP_NAME
            )
    ) {

        data.error = true;

        data.message =
            "You are not authorized to review HR leave approvals.";

        return;
    }


    data.hasAccess = true;



    // =====================================================
    // GET LEAVE REQUEST SYS_ID
    // =====================================================

    var leaveSysId = "";


    if (
        input &&
        input.leave_sys_id
    ) {

        leaveSysId =
            input.leave_sys_id;

    } else {

        leaveSysId =
            $sp.getParameter(
                'sys_id'
            );

    }


    if (!leaveSysId) {

        data.error = true;

        data.message =
            "No Leave Request was selected.";

        return;
    }



    // =====================================================
    // LOAD LEAVE REQUEST
    // =====================================================

    var leaveGR =
        new GlideRecord(
            LEAVE_TABLE
        );


    if (
        !leaveGR.get(
            leaveSysId
        )
    ) {

        data.error = true;

        data.message =
            "Leave Request could not be found.";

        return;
    }


    data.requestFound = true;



    // =====================================================
    // PROCESS APPROVE / REJECT
    // =====================================================

    if (
        input &&
        (
            input.action == 'approve' ||
            input.action == 'reject'
        )
    ) {


        processApproval(
            leaveGR,
            input.action,
            input.hr_remarks || ""
        );


        // Reload latest Leave Request state

        leaveGR.get(
            leaveSysId
        );

    }



    // =====================================================
    // CHECK WHETHER REQUEST CAN STILL BE PROCESSED
    // =====================================================

    var statusValue =
        leaveGR.getValue(
            'status'
        ) || "";


    data.canProcess =
        statusValue ==
        'pending_hr';



    // =====================================================
    // GET ATTACHMENTS
    // =====================================================

    var leaveAttachments =
        getLeaveAttachments(
            leaveGR.getUniqueValue()
        );



    // =====================================================
    // PREPARE LEAVE REQUEST DATA
    // =====================================================

    data.leave = {


        sys_id:
            leaveGR.getUniqueValue(),


        number:
            leaveGR.getDisplayValue(
                'number'
            ),


        requested_by:
            leaveGR.getDisplayValue(
                'requested_by'
            ),


        department:
            leaveGR.getDisplayValue(
                'department'
            ),


        leave_type:
            leaveGR.getDisplayValue(
                'leave_type'
            ),


        start_date:
            leaveGR.getDisplayValue(
                'start_date'
            ),


        end_date:
            leaveGR.getDisplayValue(
                'end_date'
            ),


        number_of_days:
            leaveGR.getDisplayValue(
                'number_of_leave_days'
            ),


        reason:
            leaveGR.getDisplayValue(
                'reason'
            ),


        emergency_reason:
            leaveGR.getDisplayValue(
                'emergency_reason'
            ),


        hod_remarks:
            leaveGR.getDisplayValue(
                'hod_remarks'
            ),


        hr_remarks:
            leaveGR.getDisplayValue(
                'hr_remarks'
            ),


        comments:
            leaveGR.getDisplayValue(
                'comments'
            ),


        applied_on:
            leaveGR.getDisplayValue(
                'applied_on'
            ),


        approval_group:
            leaveGR.getDisplayValue(
                'approval_group'
            ),


        current_approver:
            leaveGR.getDisplayValue(
                'current_approver'
            ),


        status:
            leaveGR.getDisplayValue(
                'status'
            ),


        status_value:
            statusValue,


        // =====================================
        // EMPLOYEE ATTACHMENTS
        // =====================================

        attachments:
            leaveAttachments

    };



    // =====================================================
    // FIND CURRENT PENDING APPROVAL
    // =====================================================

    function getPendingApproval(
        requestSysId
    ) {


        var approvalGR =
            new GlideRecord(
                APPROVAL_TABLE
            );


        approvalGR.addQuery(
            'state',
            'requested'
        );


        approvalGR.addQuery(
            'approver',
            userId
        );


        // ---------------------------------------------
        // LINK APPROVAL TO LEAVE REQUEST
        // ---------------------------------------------

        var approvalCondition;


        if (
            approvalGR.isValidField(
                'sysapproval'
            )
        ) {

            approvalCondition =
                approvalGR.addQuery(
                    'sysapproval',
                    requestSysId
                );


            if (
                approvalGR.isValidField(
                    'document_id'
                )
            ) {

                approvalCondition
                    .addOrCondition(
                        'document_id',
                        requestSysId
                    );

            }

        } else if (
            approvalGR.isValidField(
                'document_id'
            )
        ) {

            approvalGR.addQuery(
                'document_id',
                requestSysId
            );

        }


        approvalGR.orderByDesc(
            'sys_created_on'
        );


        approvalGR.setLimit(1);


        approvalGR.query();


        if (
            approvalGR.next()
        ) {

            return approvalGR;
        }


        return null;
    }



    // =====================================================
    // PROCESS HR APPROVAL
    // =====================================================

    function processApproval(
        requestGR,
        action,
        remarks
    ) {


        var currentStatus =
            requestGR.getValue(
                'status'
            );


        // ---------------------------------------------
        // STATUS CHECK
        // ---------------------------------------------

        if (
            currentStatus !=
            'pending_hr'
        ) {


            data.actionResult = {

                success: false,

                message:
                    "This Leave Request is no longer waiting for HR approval."

            };


            return;
        }



        // ---------------------------------------------
        // CLEAN REMARKS
        // ---------------------------------------------

        remarks =
            (remarks || "")
                .toString()
                .trim();



        // ---------------------------------------------
        // REMARKS REQUIRED FOR REJECTION
        // ---------------------------------------------

        if (
            action == 'reject' &&
            !remarks
        ) {


            data.actionResult = {

                success: false,

                message:
                    "HR Remarks are required when rejecting a Leave Request."

            };


            return;
        }



        // ---------------------------------------------
        // SAVE HR REMARKS
        // ---------------------------------------------

        if (remarks) {


            requestGR.setValue(
                'hr_remarks',
                remarks
            );


            requestGR.update();

        }



        // ---------------------------------------------
        // FIND FLOW DESIGNER APPROVAL RECORD
        // ---------------------------------------------

        var approvalGR =
            getPendingApproval(
                requestGR.getUniqueValue()
            );



        if (!approvalGR) {


            data.actionResult = {

                success: false,

                message:
                    "No pending HR approval record was found for this user."

            };


            return;
        }



        // =================================================
        // APPROVE
        // =================================================

        if (
            action ==
            'approve'
        ) {


            approvalGR.setValue(
                'state',
                'approved'
            );


            approvalGR.update();


            data.actionResult = {

                success: true,

                decision:
                    'approved',

                message:
                    "Leave Request approved successfully. The workflow will continue processing the final approval."

            };


            return;
        }



        // =================================================
        // REJECT
        // =================================================

        if (
            action ==
            'reject'
        ) {


            approvalGR.setValue(
                'state',
                'rejected'
            );


            approvalGR.update();


            data.actionResult = {

                success: true,

                decision:
                    'rejected',

                message:
                    "Leave Request rejected successfully. The workflow will continue processing the rejection."

            };

        }

    }

})();
